+name: "Setup"
+description: "Optionally: install node modules, set up GCloud, fetch base commit, install Cypress"
+
+inputs:
+    token:
+        description: "GitHub token to use for authentication (needs packages:read permission)"
+        required: false
+        default: ${{ github.token }}
+    ssh-key:
+        description: >-
+            A private SSH key so that we can obtain private dependencies like
+            our event schema package. Required when install-node-modules is
+            true.
+        required: false
+    install-node-modules:
+        description: "Whether to install node modules via pnpm install."
+        required: false
+        default: "true"
+    setup-gcloud:
+        description: "Whether to authenticate and configure Google Cloud."
+        required: false
+        default: "false"
+    fetch-base-commit:
+        description: "Whether to determine the base commit for Turbo SCM delta analysis."
+        required: false
+        default: "false"
+    install-cypress:
+        description: >-
+            Whether to install Cypress and cache the binary (big cache so use
+            sparingly). Also sets up Google Cloud (required for Cypress secret
+            manager access).
+        required: false
+        default: "false"
+
+outputs:
+    base-commit:
+        description: >-
+            The SHA of the base commit that we should compare against (only
+            set when fetch-base-commit is true)
+        value: ${{ steps.basecommitinfo.outputs.base-commit }}
+
+runs:
+    using: "composite"
+    steps:
+        - uses: pnpm/action-setup@41ff72655975bd51cab0327fa583b6e92b6d3061 # v4
+          name: Install pnpm
+          if: inputs.install-node-modules == 'true'
+          with:
+              run_install: false
+              package_json_file: "package.json"
+
+        - name: Use Node.js 24.x
+          if: inputs.install-node-modules == 'true'
+          uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4
+          with:
+              node-version: "24.x"
+              cache: "pnpm"
+              cache-dependency-path: "pnpm-lock.yaml"
+
+        - uses: webfactory/ssh-agent@dc588b651fe13675774614f8e6a936a468676387 # v0.9.0
+          if: inputs.install-node-modules == 'true'
+          with:
+              ssh-private-key: ${{ inputs.ssh-key }}
+
+        - name: Authorize GitHub Packages
+          if: inputs.install-node-modules == 'true'
+          working-directory: ./
+          shell: bash
+          env:
+              PNPM_TOKEN: ${{ inputs.token }}
+          run: pnpm auth -t "$PNPM_TOKEN"
+
+        - name: Install Static Dependencies
+          if: inputs.install-node-modules == 'true'
+          working-directory: ./
+          shell: bash
+          run: pnpm install --frozen-lockfile --prefer-offline
+
+        - name: Authenticate to Google Cloud
+          if: inputs.setup-gcloud == 'true' || inputs.install-cypress == 'true'
+          id: auth
+          uses: google-github-actions/auth@c200f3691d83b41bf9bbd8638997a462592937ed # v2
+          with:
+              workload_identity_provider: "projects/179486897809/locations/global/workloadIdentityPools/github-action-pool/providers/github-action-provider"
+              service_account: "github-action-webapp@khan-academy.iam.gserviceaccount.com"
+
+        - name: Setup Gcloud
+          if: inputs.setup-gcloud == 'true' || inputs.install-cypress == 'true'
+          uses: "google-github-actions/setup-gcloud@e427ad8a34f8676edf47cf7d7925499adf3eb74f" # v2
+          with:
+              project_id: 179486897809
+
+        - name: Get commit SHA for main
+          id: getmainsha
+          if: inputs.fetch-base-commit == 'true'
+          shell: bash
+          env:
+              GH_TOKEN: ${{ inputs.token }}
+              CURRENT_SHA: ${{ github.sha }}
+          run: |
+              MAIN_MERGE_BASE=$(gh api repos/Khan/frontend/compare/main...$CURRENT_SHA --jq '.merge_base_commit.sha')
+              MAIN_SHA=$(git ls-remote -q origin refs/heads/main | awk '{print $1}')
+              echo "main branch SHA: $MAIN_SHA"
+              echo "merge base SHA: $MAIN_MERGE_BASE"
+              echo "main-sha=$MAIN_SHA" >> "$GITHUB_OUTPUT"
+
+        - name: Get Base Commit Info
+          id: basecommitinfo
+          if: inputs.fetch-base-commit == 'true'
+          shell: bash
+          working-directory: ./
+          env:
+              GITHUB_TOKEN: ${{ inputs.token }}
+              SWC_NODE_IGNORE_DYNAMIC: 1
+              MAIN_SHA: ${{ steps.getmainsha.outputs.main-sha }}
+          run: ./libs/dev/github/src/bin/base-commit-info.ts "$MAIN_SHA"
+
+        - name: Check out additional history
+          if: inputs.fetch-base-commit == 'true'
+          uses: actions/checkout@34e114876b0b11c390a56381ad16ebd13914f8d5 # v4
+          with:
+              # We need to fetch enough history to compare the current commit
+              # to the base commit, which is determined in the previous step.
+              fetch-depth: ${{ steps.basecommitinfo.outputs.fetch-depth }}
+              # We don't want to have to go and get all the node_modules again
+              clean: false
+
+        - name: Install & cache Cypress
+          if: inputs.install-cypress == 'true'
+          uses: ./.github/actions/cypress-install
